def rot(p):
    q=[0]*n
    for i,v in enumerate(p): q[v]=n-1-i
    return tuple(q)
def refl(p): return tuple(reversed(p))
def orbit(p):
    out=set();q=p
    for _ in range(4):
        out.add(q);out.add(refl(q));q=rot(q)
    return min(out)
